(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"two-vectors":{"h":"WHAT YOU ARE LOOKING AT","t":"Two vectors, **u and v**. We want a number that says **how much they point the same way**."},"dot-product":{"h":"THE DOT PRODUCT","t":"Multiply matching entries and add: **u · v = u₁v₁ + u₂v₂**. The result is **one number**."},"aligned":{"h":"POINTING THE SAME WAY","t":"When v points the same way as u, the dot product is **large and positive**: the vectors share a lot of direction."},"perpendicular":{"h":"TURN v TO A RIGHT ANGLE","t":"Rotate v until it makes a **right angle** with u. They no longer share any direction."},"zero-dot":{"h":"PERPENDICULAR MEANS DOT PRODUCT 0","t":"At **90°** the dot product is exactly **0**. Vectors with **u · v = 0** are called **orthogonal**."},"ml-meaning":{"h":"TAKEAWAY","t":"**Orthogonal directions are independent**: they do not overlap, so each coordinate can be read off separately. That is why machine learning likes them."}};
  // ── scene ──
  var steps = [
    { id: "two-vectors", label: "Two vectors", caption: "Take two vectors, u and v. We want a number that says how much they point the same way." },
    { id: "dot-product", label: "The dot product", caption: "Multiply matching entries and add: u · v = u₁v₁ + u₂v₂. The result is one number." },
    { id: "aligned", label: "Pointing the same way", caption: "When v points the same way as u, the dot product is large and positive." },
    { id: "perpendicular", label: "Turn v to a right angle", caption: "Rotate v until it makes a right angle with u. They no longer share any direction." },
    { id: "zero-dot", label: "Perpendicular means dot product 0", caption: "At 90° the dot product is exactly 0. Vectors with u · v = 0 are called orthogonal." },
    { id: "ml-meaning", label: "Orthogonal directions are independent", caption: "Perpendicular directions do not overlap, so each coordinate can be read off independently. That is why ML likes them." }
  ];

  var P = makePlane(240, 190, 44);
  axes(svg, P, 4.3, 4);
  var U = [3, 0];
  var LEN = 2.5;

  var arrU = arrow(svg, "b", 4);
  setLine(arrU, P.x(0), P.y(0), P.x(U[0]), P.y(U[1]));
  txt(svg, P.x(U[0]) + 10, P.y(0) + 5, "lbl lbl-b", "u");
  var arrV = arrow(svg, "p", 4);
  var labV = txt(svg, 0, 0, "lbl lbl-p", "v");
  var arcPath = el("path", { fill: "none", stroke: "#e2b44a", "stroke-width": 2 }, svg);
  var rightSq = el("polyline", { fill: "none", stroke: "#e2b44a", "stroke-width": 2, opacity: 0 }, svg);
  var angleLab = txt(svg, P.x(0) + 40, P.y(0) - 14, "lbl lbl-y", "");

  // Readout panel on the right.
  var panel = el("g", {}, svg);
  el("rect", { x: 440, y: 40, width: 188, height: 136, rx: 12, class: "fillG" }, panel);
  txt(panel, 534, 66, "lbl", "u · v", "middle");
  var calc = txt(panel, 534, 100, "mono", "", "middle");
  var value = txt(panel, 534, 142, "big", "", "middle");
  var meaning = txt(panel, 534, 164, "note", "", "middle");

  var proj = el("g", { opacity: 0 }, svg);
  var dropX = el("line", { class: "dash", stroke: "#c9dccf", "stroke-width": 1.5 }, proj);
  var dropY = el("line", { class: "dash", stroke: "#c9dccf", "stroke-width": 1.5 }, proj);
  var pointP = el("circle", { r: 6, fill: "#e2b44a" }, proj);
  var axisNote = txt(svg, 320, 334, "note", "", "middle");

  var theta = 50; // degrees
  function drawVector() {
    var rad = (theta * Math.PI) / 180;
    var vx = LEN * Math.cos(rad);
    var vy = LEN * Math.sin(rad);
    setLine(arrV, P.x(0), P.y(0), P.x(vx), P.y(vy));
    labV.setAttribute("x", P.x(vx) + 10);
    labV.setAttribute("y", P.y(vy) - 6);
    var r = 0.9;
    arcPath.setAttribute("d", "M " + P.x(r) + " " + P.y(0) + " A " + r * P.s + " " + r * P.s + " 0 0 0 " + P.x(r * Math.cos(rad)) + " " + P.y(r * Math.sin(rad)));
    // Show the arithmetic with the same rounded components that are printed, so the readout always adds up.
    var shownX = Number(round1(vx));
    var shownY = Number(round1(vy));
    var dot = U[0] * shownX + U[1] * shownY;
    angleLab.textContent = Math.round(theta) + "°";
    calc.textContent = "3×" + round1(vx) + " + 0×" + round1(vy);
    value.textContent = "= " + round1(dot);
    meaning.textContent = dot > 0.05 ? "positive: same general direction" : dot < -0.05 ? "negative: opposite directions" : "zero: perpendicular";
    show(rightSq, Math.abs(theta - 90) < 0.5);
    if (Math.abs(theta - 90) < 0.5) {
      rightSq.setAttribute("points", P.x(0.45) + "," + P.y(0) + " " + P.x(0.45) + "," + P.y(0.45) + " " + P.x(0) + "," + P.y(0.45));
    }
  }

  function turnTo(target, ms) {
    var from = theta;
    anim("theta", ms, function (e) { theta = lerp(from, target, e); drawVector(); });
  }

  function render(index, id) {
    show(panel, id !== "two-vectors");
    show(proj, false);
    axisNote.textContent = "";
    show(angleLab, id !== "two-vectors" && id !== "ml-meaning");
    show(arcPath, id !== "ml-meaning");
    if (id === "two-vectors") turnTo(50, 400);
    else if (id === "dot-product") turnTo(50, 400);
    else if (id === "aligned") turnTo(8, 800);
    else if (id === "perpendicular") turnTo(90, 900);
    else if (id === "zero-dot") turnTo(90, 200);
    else {
      turnTo(90, 200);
      show(panel, false);
      show(proj, true);
      // A point read along two perpendicular directions: coordinates are independent.
      var px = 2.2, py = 1.8;
      setLine(dropX, P.x(px), P.y(py), P.x(px), P.y(0));
      setLine(dropY, P.x(px), P.y(py), P.x(0), P.y(py));
      pointP.setAttribute("cx", P.x(px));
      pointP.setAttribute("cy", P.y(py));
      axisNote.textContent = "Each coordinate is measured along its own perpendicular direction";
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

